from __future__ import absolute_import
import time
import logging
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts.pages.panels.view import ViewPanel
from taf.selenium.sbts.pages.panels.details import DetailPanel
from taf.selenium.sbts.pages.panels.navigation import NavigationPanel
from taf.selenium.sbts.common.exceptions import EditionError, ButtonCanNotClick
from taf.selenium.sbts.pages.configuration.configuration_management import ConfigurationCommonAction
from taf.selenium.sbts.pages.navigatable_page import NavigatablePage


class ParameterEditorPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on Parameter Editor will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Configuration', 'Configuration Management', 'Parameter Editor']

    def __init__(self, driver, download_checker, screenshot_dir):
        super(ParameterEditorPage, self).__init__(driver)
        self._navigation_panel = ParameterEditorPageNavigationPanel(driver, screenshot_dir)
        self._view_panel = ParameterEditorPageViewPanel(driver, download_checker)
        self._detail_panel = ParameterEditorPageDetailPanel(driver)
        self.common_actions = {
            'add_object': self._navigation_panel.add_object,
            'remove_object': self._navigation_panel.remove_object,
            'undo_object_changes': self._navigation_panel.undo_object_changes,
            'create_plan': self._view_panel.create_plan,
            'load_commissioning_file_and_check_load_status':
                self._view_panel.load_commissioning_file_and_check_load_status,
            'undo_changes': self._view_panel.undo_changes,
            'validate_plan': self._view_panel.validate_plan,
            'activate_plan': self._view_panel.activate_plan,
            'save_report': self._view_panel.save_report,
            'save_bts_configuration': self._view_panel.save_bts_configuration,
        }
        self.__dict__.update(self.common_actions)

    def get_parameter_value_by_global_search(self, filter_param, timeout=60):
        return self._view_panel.get_parameter_value_by_global_search(filter_param, timeout)

    def get_parameter_value(self, dist_name, filter_param, node_index=None, abbr=None, bts_configuration='Current',
                            timeout=60):
        """
        Keyword for getting parameter value at Parameter Editor view
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param node_index: int, param to filter child node if other params can not locate only one
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param bts_configuration: optional, "Current" or "Planned" bts configuration can be used
        :param timeout: int, timeout
        :return: str, the value corresponding to filter_param
        """
        return self._view_panel.get_parameter_value(dist_name, filter_param, node_index, abbr, bts_configuration,
                                                    timeout)

    def get_planned_parameter_value(self, dist_name, filter_param, node_index=None, abbr=None,
                                    bts_configuration='Current', timeout=60):
        return self._view_panel.get_planned_parameter_value(dist_name, filter_param, node_index, abbr,
                                                            bts_configuration, timeout)

    def set_parameter_value(self, dist_name, filter_param, new_value, node_index=None,
                            parameter_status="All parameters", abbr=None, bts_configuration='Current', timeout=60):
        self._view_panel.set_parameter_value(dist_name, filter_param, new_value, node_index,
                                             parameter_status, abbr, bts_configuration, timeout)

    def get_error_info_after_set_parameter(self, timeout=2):
        """
        Keyword for getting parameter error info after setting parameter value
        """
        return self._view_panel.get_error_info_after_set_parameter(timeout)

    def add_element(self, dist_name, filter_param, abbr=None, timeout=60):
        """
        Keyword for adding element under child node of one object
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param timeout: int, timeout
        """
        self._view_panel.add_element(dist_name, filter_param, abbr, timeout)

    def remove_element(self, dist_name, filter_param, node_index=0, abbr=None, timeout=60):
        """
        Keyword for removing element under child node of one object
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param node_index: int, param to filter child node if other params can not locate only one
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param timeout: int, timeout
        """
        self._view_panel.remove_element(dist_name, filter_param, node_index, abbr, timeout)

    def delete_parameter(self, dist_name, filter_param, node_index=None, abbr=None, timeout=60):
        """
        Delete parameter
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param node_index: int, param to filter child node if other params can not locate only one
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param timeout: int, timeout
        """
        self._view_panel.delete_parameter(dist_name, filter_param, node_index, abbr, timeout)

    def get_parameter_details(self, dist_name, filter_param, abbr=None, timeout=60):
        """
        Keyword for getting parameter details at Parameter Editor view
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param timeout: int, timeout
        :return: dict of str
        """
        return self._detail_panel.get_parameter_details(dist_name, filter_param, abbr, timeout)

    def get_object_name_list(self, object_name, bts_configuration='Current', timeout=60):
        """
        Keyword for getting specific name list at Parameter Editor view

        :param object_name: param object_name: name to locate target object, cannot be none
        :type object_name: str
        :param bts_configuration: optional, "Current" or "Planned" bts configuration can be used
        :type bts_configuration: str
        :param timeout: timeout
        :type timeout: int
        :return: the name list of specific name
        :rtype: list
        """
        return self._view_panel.get_object_name_list(object_name, bts_configuration, timeout)

    def get_dist_name_list_by_object_name(self, object_name, bts_configuration='Current', timeout=60):
        """
        Keyword for getting specific name list at Parameter Editor view

        :param object_name: param object_name: name to locate target object, cannot be none
        :type object_name: str
        :param bts_configuration: optional, "Current" or "Planned" bts configuration can be used
        :type bts_configuration: str
        :param timeout: timeout
        :type timeout: int
        :return: the name list of specific name
        :rtype: list
        """
        return self._view_panel.get_dist_name_list_by_object_name(object_name, bts_configuration, timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class ParameterEditorPageNavigationPanel(NavigationPanel):
    def __init__(self, driver, screenshot_dir):
        super(ParameterEditorPageNavigationPanel, self).__init__(driver)
        common_action = ConfigurationCommonAction(driver, screenshot_dir=screenshot_dir)
        self.common_actions = {
            'add_object': common_action.add_object,
            'remove_object': common_action.remove_object,
            'undo_object_changes': common_action.undo_object_changes
        }
        self.__dict__.update(self.common_actions)


class ParameterEditorPageViewPanel(ViewPanel):
    _PARAM_NAME_INPUT_XPATH = ('//*[contains(@class, "pe-table-header-container")]'
                               '//th[@class="pe-full-name-cell"]//input')
    _ABBREVIATION_INPUT_XPATH = ('//*[contains(@class, "pe-table-header-container")]'
                                 '//th[@class="pe-abbreviation-cell"]//input')
    _PLANNED_VALUE_BASE_XPATH = ('//highlighter[translate(@title, "ABCDEFGHIJKLMNOPQRSTUVWXYZ", '
                                 '"abcdefghijklmnopqrstuvwxyz")="{0}"]/ancestor::tr[1]')
    _PLANNED_VALUE_BUTTON_XPATH = _PLANNED_VALUE_BASE_XPATH + '//td[contains(@class, "pe-value")]//button'
    _PLANNED_VALUE_LIST_XPATH = _PLANNED_VALUE_BASE_XPATH + "//td[4]//ul//a"
    _PLANNED_VALUE_INPUT_XPATH = _PLANNED_VALUE_BASE_XPATH + '//td[4]//input'
    _SPECIAL_PLANNED_VALUE_INPUT_XPATH = ('//highlighter[translate(@title, "ABCDEFGHIJKLMNOPQRSTUVWXYZ", '
                                          '"abcdefghijklmnopqrstuvwxyz")="{}"]/ancestor::tbody'
                                          '//*[text()="#{}"]/ancestor::tr[1]//input')
    _ACTUAL_VALUE_XPATH = _PLANNED_VALUE_BASE_XPATH + '//td[5]/span'
    _ACTUAL_VALUE_MULTI_SELECT_BUTTON = _PLANNED_VALUE_BASE_XPATH + '//td[5]//ui-multiselect//button'
    _ACTUAL_VALUE_MULTI_OPTION_LABEL = _PLANNED_VALUE_BASE_XPATH + ('//td[5]//ui-multiselect//span[contains'
                                                                    '(@class, "multiselect-option-label")]')
    _SPECIAL_ACTUAL_VALUE_XPATH = ('//highlighter[translate(@title, "ABCDEFGHIJKLMNOPQRSTUVWXYZ", '
                                   '"abcdefghijklmnopqrstuvwxyz")="{}"]/ancestor::tbody//*[text()="#{}"]'
                                   '/ancestor::tr[1]//td[contains(@class, "actual-value")]')
    _SET_DEFAULT_PARAMETER_VALUE_XPATH = (_PLANNED_VALUE_BASE_XPATH + '//button[@ui-tooltip='
                                                                      '"Set default parameter value"]')
    _ADD_ELEMENT_BUTTON_XPATH = _PLANNED_VALUE_BASE_XPATH + '//button[@ui-tooltip="Add Element"]'
    _REMOVE_ELEMENT_BUTTON_XPATH = ('//highlighter[translate(@title, "ABCDEFGHIJKLMNOPQRSTUVWXYZ", '
                                    '"abcdefghijklmnopqrstuvwxyz")="{}"]/ancestor::tbody//*[text()="Structure {}" '
                                    'or text()="#{}"]/ancestor::tr[1]//button[@*="Remove Element"]')
    _DELETE_PARAMETER_BUTTON_XPATH = _PLANNED_VALUE_BASE_XPATH + '//button[@ui-tooltip="Delete parameter"]'
    _ERROR_WINDOW_XPATH = '//div[contains(@class, "ui-popover-error")]'
    _PARAMETER_STATUS_DROPDOWN_BUTTON_XPATH = '//div[contains(@class, "pe-filter-text")]'
    _TARGET_PARAMETER_STATUS_XPATH = '//label[text()="{}"]'
    _OBJECT_NAME_FILTER_XPATH = '//ui-text-input[@a-type="filter" and @a-placeholder="Object name"]//input'
    _OBJECT_NAME_MAP_XPATH = ('//*[contains(text(), "{}")]/ancestor::*[contains(@class, '
                              '"tree-list-grouping-renderer ng-scope")]//span[contains(@aria-label, "{}")]')
    _SEARCH_ALL_INPUT_XPATH = '//*[contains(@class, "configuration-container")]//input[@type="search"]'
    _CLEAR_GLOBAL_SEARCH = _SEARCH_ALL_INPUT_XPATH + '//parent::div//following-sibling::div//i[@role="button"]'
    _PARAMETER_NAME = 'Parameter name'
    _ACTUAL_VALUE = 'Actual Value'
    _LI_XPATH = ('//ui-expandable-panel-header[contains(text(), "Current")]/ancestor::ui-expandable-panel'
                 '//following-sibling::li[contains(@class, "tree-list")]')
    _VALID_OBJECT_BASE_XPATH = '//ui-expandable-panel-header[contains(text(), "{}")]/ancestor::ui-expandable-panel/'
    _TARGET_OBJECT_XPATH = '/following-sibling::li[div//span[@aria-label="{}"]]'
    _SCROLL_TOP = 'return document.querySelector(\'global-search-tab-content div[virtual-scroll="true"]\').scrollTop'
    _SCROLL = ('var scroll_bar = document.querySelector(\'global-search-tab-content div[virtual-scroll="true"]\'); '
               'if (scroll_bar){{scroll_bar.scrollTop={};}}')
    _STEP = 120

    def __init__(self, driver, download_checker=None):
        super(ParameterEditorPageViewPanel, self).__init__(driver)
        common_action = ConfigurationCommonAction(driver, download_checker)
        self.common_actions = {
            '_input_and_choose_object': common_action._input_and_choose_object,
            '_input_object': common_action._input_object,
            'load_commissioning_file_and_check_load_status':
                common_action.load_commissioning_file_and_check_load_status,
            'undo_changes': common_action.undo_changes,
            'validate_plan': common_action.validate_plan,
            'activate_plan': common_action.activate_plan,
            'save_report': common_action.save_report,
            'save_bts_configuration': common_action.save_bts_configuration,
            'create_plan': common_action.create_plan,
        }
        self.__dict__.update(self.common_actions)

    def _input_object_name_and_filter_param(self, object_name, filter_param, timeout=60, bts_configuration='Current'):
        """
        Input object name and filter parameter
        """
        self._input_and_choose_object(object_name, timeout, bts_configuration)
        self.insert_text_to_enable_element((By.XPATH, self._PARAM_NAME_INPUT_XPATH), filter_param, timeout)

    def _select_parameter_status(self, parameter_status):
        if parameter_status != self.get_text_by_xpath(self._PARAMETER_STATUS_DROPDOWN_BUTTON_XPATH):
            self.select_element_from_dropdown_list_by_text_and_click(
                parameter_status,
                (By.XPATH, self._PARAMETER_STATUS_DROPDOWN_BUTTON_XPATH),
                (By.XPATH, self._TARGET_PARAMETER_STATUS_XPATH.format(parameter_status))
            )
            self.click_enabled_element((By.XPATH, self._PARAMETER_STATUS_DROPDOWN_BUTTON_XPATH))

    def _input_abbreviation(self, abbr, timeout):
        if abbr:
            self.insert_text_to_enable_element_and_enter((By.XPATH, self._ABBREVIATION_INPUT_XPATH), abbr, timeout)

    def _clear_abbreviation(self):
        elem = self.driver.find_element_by_xpath(self._ABBREVIATION_INPUT_XPATH)
        self._clear_text_of_field(elem)

    def _search_all(self, filter_param, timeout=60):
        self.insert_text_to_enable_element_and_enter((By.XPATH, self._SEARCH_ALL_INPUT_XPATH), filter_param, timeout)

    def get_parameter_value_by_global_search(self, filter_param, timeout=60):
        self._search_all(filter_param, timeout)
        outcome = []
        try:
            self.wait_for_visibility_by_xpath(self._ACTUAL_VALUE_XPATH.format(filter_param.lower()))
            for elem in self.driver.find_elements_by_xpath(self._ACTUAL_VALUE_XPATH.format(filter_param.lower())):
                outcome.append({self._PARAMETER_NAME: filter_param,
                                self._ACTUAL_VALUE: elem.text.strip()})
        except TimeoutException:
            pass
        self.click_enabled_element((By.XPATH, self._CLEAR_GLOBAL_SEARCH), timeout)
        return outcome

    def get_parameter_value(self, dist_name, filter_param, node_index=None, abbr=None, bts_configuration='Current',
                            timeout=60):
        """
        Get parameter value at Parameter Editor view
        """
        self._input_object_name_and_filter_param(dist_name, filter_param, timeout, bts_configuration)
        self._clear_abbreviation()
        self._input_abbreviation(abbr, timeout)

        filter_param = filter_param.lower()
        if self.element_exists((By.XPATH, self._ACTUAL_VALUE_MULTI_SELECT_BUTTON.format(filter_param))):
            self.click_and_wait_for_corresponding_element_visible(
                self._ACTUAL_VALUE_MULTI_SELECT_BUTTON.format(filter_param),
                self._ACTUAL_VALUE_MULTI_OPTION_LABEL.format(filter_param)
            )
            return [elem.text.strip() for elem in
                    self.driver.find_elements_by_xpath(self._ACTUAL_VALUE_MULTI_OPTION_LABEL.format(filter_param))]

        if node_index is not None:
            node_index = int(node_index)
            _SPECIAL_ACTUAL_VALUE_XPATH = self._SPECIAL_ACTUAL_VALUE_XPATH.format(filter_param, node_index + 1)
            if self.element_exists((By.XPATH, _SPECIAL_ACTUAL_VALUE_XPATH)):
                return self.get_text_by_xpath(_SPECIAL_ACTUAL_VALUE_XPATH)
            return self.driver.find_elements_by_xpath(self._ACTUAL_VALUE_XPATH.format(filter_param))[node_index].text
        else:
            return self.get_text_by_xpath(self._ACTUAL_VALUE_XPATH.format(filter_param))

    def get_planned_parameter_value(self, dist_name, filter_param, node_index=None, abbr=None,
                                    bts_configuration='Current', timeout=60):
        """
        Get planned parameter value at Parameter Editor view
        """
        self._input_object_name_and_filter_param(dist_name, filter_param, timeout, bts_configuration)
        self._clear_abbreviation()
        self._input_abbreviation(abbr, timeout)

        filter_param = filter_param.lower()
        if self.element_exists((By.XPATH, self._PLANNED_VALUE_BUTTON_XPATH.format(filter_param)), 3):
            return self._get_parameter_value_from_dropdown_list(filter_param, node_index)
        else:
            return self._get_parameter_value_from_input(filter_param, node_index)

    def _get_parameter_value_from_dropdown_list(self, filter_param, node_index=None):
        dropdown_list_button_xpath = self._PLANNED_VALUE_BUTTON_XPATH.format(filter_param)
        if node_index is not None:
            element = self.driver.find_elements_by_xpath(dropdown_list_button_xpath)[int(node_index)]
            element.click()
        else:
            self.click_enabled_element((By.XPATH, dropdown_list_button_xpath))
            element = self.driver.find_element_by_xpath(dropdown_list_button_xpath)
        dropdown_elements = element.find_elements_by_xpath('./parent::*/ul//li')
        return [elem.text for elem in dropdown_elements]

    def _get_parameter_value_from_input(self, filter_param, node_index=None):
        planned_elem = None
        if node_index is not None:
            planned_elem = self._find_input_element_under_multiple_level_parameters(filter_param, node_index)
        else:
            planned_elem = self.driver.find_element_by_xpath(self._PLANNED_VALUE_INPUT_XPATH.format(filter_param))
        return planned_elem.get_attribute('value')

    def _choose_value_if_checkbox_exist(self, check_box_xpath, value):
        """
        Choose checkbox according to given value
        :param check_box_xpath: str, xpath
        :param value: list, list contains str value
        """
        value = [str(item) for item in value]
        for element in self.driver.find_elements_by_xpath(check_box_xpath):
            is_checked = element.is_selected()
            span_item = element.find_element_by_xpath('./../..')
            self.driver.execute_script("arguments[0].scrollIntoView();", span_item)
            if not is_checked and span_item.text in value:
                span_item.click()
            elif is_checked and span_item.text not in value:
                span_item.click()

    def _select_parameter(self, filter_param, new_value):
        dropdown_items_xpath = self._PLANNED_VALUE_LIST_XPATH.format(filter_param)
        check_box_xpath = dropdown_items_xpath + '//input'
        if self.element_exists((By.XPATH, check_box_xpath)):
            self._choose_value_if_checkbox_exist(check_box_xpath, new_value)
        else:
            dropdown_elements = self.driver.find_elements_by_xpath(dropdown_items_xpath)
            self.find_element_from_group_by_text(dropdown_elements, new_value).click()

    def _select_parameter_value_from_dropdown_list(self, filter_param, new_value, node_index=None):
        """
        Select a value according to new_value from drop down list after it opened
        """
        dropdown_list_xpath = self._PLANNED_VALUE_BUTTON_XPATH.format(filter_param)
        if node_index is not None:
            element = self.driver.find_elements_by_xpath(dropdown_list_xpath)[int(node_index)]
            element.click()
            dropdown_elements = element.find_elements_by_xpath('./parent::*/ul//li')
            self.find_element_from_group_by_text(dropdown_elements, new_value).click()
        else:
            """
            The dropdown list will be closed sometimes before select value operation finished,
            Retry it to avoid this issue.
            """
            retry_times = 3
            for _ in range(retry_times):
                try:
                    self.click_enabled_element((By.XPATH, dropdown_list_xpath))
                    self._select_parameter(filter_param, new_value)
                    break
                except AttributeError:
                    logging.info("select dropdown list value failed, and retry {} again".format(retry_times))
                    continue

    def _find_input_element_under_multiple_level_parameters(self, filter_param, node_index):
        if self.element_exists(
                (By.XPATH, self._SPECIAL_PLANNED_VALUE_INPUT_XPATH.format(filter_param, node_index + 1)), 3):
            return self.driver.find_element_by_xpath(
                self._SPECIAL_PLANNED_VALUE_INPUT_XPATH.format(filter_param, node_index + 1)
            )
        else:
            return self.driver.find_elements_by_xpath(
                self._PLANNED_VALUE_INPUT_XPATH.format(filter_param))[int(node_index)]

    def _input_parameter_new_value(self, filter_param, new_value, node_index=None):
        """
        Input a value according to new_value
        """
        error_window_js = ('window.get_info = function(){setTimeout(function()'
                           '{window.info = $(".ui-popover-error").text();},1000)};$(document).on("keyup", get_info)')
        if node_index is not None:
            planned_elem = self._find_input_element_under_multiple_level_parameters(filter_param, node_index)
        else:
            planned_elem = self.driver.find_element_by_xpath(self._PLANNED_VALUE_INPUT_XPATH.format(filter_param))
        if not planned_elem.is_enabled():
            raise EditionError('The planned value parameter is invalid')

        self.driver.execute_script(error_window_js)
        self._insert_text_to_field(new_value, planned_elem)

    def set_parameter_value(self, dist_name, filter_param, new_value=None, node_index=None,
                            parameter_status="All parameters", abbr=None, bts_configuration='Current', timeout=60):
        """
        Set parameter value at Parameter Editor view
        """
        self._input_object_name_and_filter_param(dist_name, filter_param, timeout, bts_configuration)
        self._select_parameter_status(parameter_status)
        self._input_abbreviation(abbr, timeout)

        filter_param = filter_param.lower().replace('&', '&amp;')
        if new_value is None:
            self.click_enabled_element_after_visible(
                (By.XPATH, self._SET_DEFAULT_PARAMETER_VALUE_XPATH.format(filter_param)), timeout
            )
            return

        if self.element_exists((By.XPATH, self._PLANNED_VALUE_BUTTON_XPATH.format(filter_param)), 3):
            self._select_parameter_value_from_dropdown_list(filter_param, new_value, node_index)
        else:
            self._input_parameter_new_value(filter_param, new_value, node_index)

    def get_error_info_after_set_parameter(self, timeout=2):
        """
        Keyword for getting parameter error info after setting parameter value
        """
        time.sleep(timeout)
        self.wait_for_visibility((By.XPATH, self._ERROR_WINDOW_XPATH), timeout)
        error_window_info = self.driver.execute_script("return window.info")
        return error_window_info if error_window_info else "there is no error"

    def add_element(self, dist_name, filter_param, abbr=None, timeout=60):
        """
        Add element under child node of one object
        """
        self._input_object_name_and_filter_param(dist_name, filter_param, timeout)
        self._input_abbreviation(abbr, timeout)

        filter_param = filter_param.lower()
        self.click_enabled_element((By.XPATH, self._ADD_ELEMENT_BUTTON_XPATH.format(filter_param)), timeout)

    def _click_delete_parameter_button(self, filter_param, node_index=None, timeout=60):
        delete_parameter_button_xpath = self._DELETE_PARAMETER_BUTTON_XPATH.format(filter_param)
        if node_index is not None:
            elem = self.driver.find_elements_by_xpath(delete_parameter_button_xpath)[node_index]
            if not elem.is_enabled():
                raise ButtonCanNotClick("delete parameter button is invalid")
            elem.click()
        else:
            self.click_enabled_element((By.XPATH, delete_parameter_button_xpath), timeout)

    def remove_element(self, dist_name, filter_param, node_index=0, abbr=None, timeout=60):
        """
        Remove element under child node of one object
        """
        self._input_object_name_and_filter_param(dist_name, filter_param, timeout)
        self._input_abbreviation(abbr, timeout)

        filter_param = filter_param.lower()
        remove_parameter_button_xpath = self._REMOVE_ELEMENT_BUTTON_XPATH.format(filter_param,
                                                                                 node_index + 1,
                                                                                 node_index + 1)
        self.driver.find_element_by_xpath(remove_parameter_button_xpath).click()

    def delete_parameter(self, dist_name, filter_param, node_index=None, abbr=None, timeout=60):
        """
        Delete parameter on Parameter Editor panel
        """
        self._input_object_name_and_filter_param(dist_name, filter_param, timeout)
        self._input_abbreviation(abbr, timeout)

        filter_param = filter_param.lower()
        self._click_delete_parameter_button(filter_param, node_index, timeout)

    def get_object_name_list(self, object_name, bts_configuration, timeout=60):
        """
        Get object namelist at Parameter Editor view
        """
        name_list = []
        last_detail_object_name = object_name.split('/')[-1]
        self.insert_text_to_enable_element_and_enter((By.XPATH, self._OBJECT_NAME_FILTER_XPATH),
                                                     last_detail_object_name, timeout)
        filter_object = self._OBJECT_NAME_MAP_XPATH.format(bts_configuration, last_detail_object_name)
        try:
            self.wait_for_visibility_by_xpath(filter_object, timeout)
            for object_element in self.driver.find_elements_by_xpath(filter_object):
                name_list.append(object_element.get_attribute("aria-label").strip())
        except TimeoutException:
            logging.info('can not wait for {} with {} seconds'.format(filter_object, timeout))
        return name_list

    def get_dist_name_list_by_object_name(self, object_name, bts_configuration, timeout=60):
        """
        Get dist name list at Parameter Editor view
        """
        bts_configuration = bts_configuration.lower().capitalize()
        object_name_list = object_name.split('/')
        last_level_object_name = object_name_list[-1]
        self._input_object(last_level_object_name, bts_configuration, timeout)

        scroll_time = 8
        dist_name_list = []
        for loop in range(0, scroll_time):
            li_elems = self.driver.find_elements_by_xpath(self._LI_XPATH)
            if not li_elems:
                break
            newest_li_id = li_elems[-1].get_attribute('id')

            target = self._VALID_OBJECT_BASE_XPATH.format(bts_configuration) + self._TARGET_OBJECT_XPATH.format(
                last_level_object_name)
            self.wait_for_visibility_by_xpath(target, timeout)
            elems = self.driver.find_elements_by_xpath(target)
            for elem in elems:
                elem.click()
                self.wait_for_visibility_by_xpath(self._PARAM_NAME_INPUT_XPATH, timeout)
                dist_name = self.get_text_by_xpath('//*[contains(@class, "pe-middle-panel-header")]//small')
                if dist_name not in dist_name_list:
                    dist_name_list.append(dist_name)

            if newest_li_id == self._get_newest_element_id():
                break
        return dist_name_list

    def _get_newest_element_id(self):
        scroll_top = float(self.driver.execute_script(self._SCROLL_TOP))
        self.driver.execute_script(self._SCROLL.format(scroll_top + self._STEP))
        li_elems = self.driver.find_elements_by_xpath(self._LI_XPATH)
        return li_elems[-1].get_attribute('id')


class ParameterEditorPageDetailPanel(DetailPanel):
    _DETAILS_PANEL_XPATH = '//details-panel/div'
    _DETAILS_PARAMETER_BUTTON_XPATH = _DETAILS_PANEL_XPATH + '//button'
    _PARAMETER_DETAILS_PANEL_XPATH = _DETAILS_PANEL_XPATH + '//div'
    _PARAMETER_DEFINITION_XPATH = _PARAMETER_DETAILS_PANEL_XPATH + ('/ui-expandable-panel'
                                                                    '[@ng-if="$ctrl.parameterDefinition.{}"]//span')
    _PARAMETER_DEFINITION_BTN_XPATH = _PARAMETER_DETAILS_PANEL_XPATH + ('/ui-expandable-panel'
                                                                        '[@ng-if="$ctrl.parameterDefinition.{}"]//i')
    _PARAMETER_DETAILS_PANEL_XPATH = _DETAILS_PANEL_XPATH + '//parameter-details/div/div'
    _DETAILS_PARAMETER_XPATH = _PARAMETER_DETAILS_PANEL_XPATH + '/ui-expandable-panel[1]/div'
    _PARAMETER_XPATH = ('//highlighter[translate(@title, "ABCDEFGHIJKLMNOPQRSTUVWXYZ", '
                        '"abcdefghijklmnopqrstuvwxyz")="{}"]/ancestor::tr[1]//td[2]//span')

    def __init__(self, driver):
        super(ParameterEditorPageDetailPanel, self).__init__(driver)
        self.common_actions = {
            '_input_object_name_and_filter_param':
                ParameterEditorPageViewPanel(driver)._input_object_name_and_filter_param,
            '_input_abbreviation': ParameterEditorPageViewPanel(driver)._input_abbreviation,
        }
        self.__dict__.update(self.common_actions)

    def get_parameter_details(self, dist_name, filter_param, abbr=None, timeout=60):
        """
        Keyword for getting parameter details at Parameter Editor view
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param timeout: int, timeout
        :return: dict of str
        """
        self._input_object_name_and_filter_param(dist_name, filter_param, timeout)
        self._input_abbreviation(abbr, timeout)

        filter_param = filter_param.lower()
        self.click_enabled_element((By.XPATH, self._DETAILS_PARAMETER_BUTTON_XPATH), timeout)
        self.click_enabled_element((By.XPATH, self._PARAMETER_XPATH.format(filter_param)), timeout)

        return self._get_details_of_parameter(timeout)

    def _get_details_of_parameter(self, timeout):
        parameters_details = self.get_text_by_xpath(self._DETAILS_PARAMETER_XPATH).split('\n')

        parameters_dict = {}
        for parameter in parameters_details:
            param = parameter.split(": ")
            if len(param) == 2:
                parameters_dict[param[0]] = param[1]

        description = self._get_text_from_desc(
            btn_xpath=self._PARAMETER_DEFINITION_BTN_XPATH.format('description'),
            desc_xpath=self._PARAMETER_DEFINITION_XPATH.format('description'),
            timeout=timeout)

        description_of_relationship = self._get_text_from_desc(
            btn_xpath=self._PARAMETER_DEFINITION_BTN_XPATH.format('descriptionOfRelationship'),
            desc_xpath=self._PARAMETER_DEFINITION_XPATH.format('descriptionOfRelationship'),
            timeout=timeout)

        special_value_description = self._get_text_from_desc(
            btn_xpath=self._PARAMETER_DEFINITION_BTN_XPATH.format('specialValueDescription'),
            desc_xpath=self._PARAMETER_DEFINITION_XPATH.format('specialValueDescription'),
            timeout=timeout)

        parameters_dict['Description'] = description
        parameters_dict['Description of relationship'] = description_of_relationship
        parameters_dict['Special value description'] = special_value_description

        return parameters_dict

    def _get_text_from_desc(self, btn_xpath, desc_xpath, timeout):
        try:
            status_of_description_btn = self.get_attribute_by_xpath(xpath=btn_xpath, attr_name="aria-expanded")
            if not status_of_description_btn:
                self.click_enabled_element((By.XPATH, btn_xpath), timeout)
            return self.get_text_by_xpath(desc_xpath)
        except Exception:
            return None
